// One item per streamer (Kick channel slug) on the permission list.
const slugs = String($input.first().json.streamers || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(s => /^[a-z0-9_-]{2,30}$/.test(s));
if (!slugs.length) throw new Error('Yayıncı ayarları → streamers boş');
return slugs.map(slug => ({ json: { slug } }));

// The most viewed recent clips (clip_period: day or week) across all permitted streamers. Viewers
// clip the hype moments themselves, so the view count is the hype score. Skip clips
// already used and streamers posted in the last 8 hours so the day's three Shorts mix
// different streamers.
const cfg = $('Yayıncı ayarları').first().json;
const state = $getWorkflowStaticData('global');
state.used = state.used || [];
state.recent = (state.recent || []).filter(r => Date.now() - r.at < 8 * 3600e3);
const used = new Set(state.used);
const recent = new Set(state.recent.map(r => r.slug));

// Fresh clips (last 48 h) count double, so today's moments win over last week's.
const score = c => (c.view_count ?? c.views ?? 0) * (Date.now() - Date.parse(c.created_at) < 48 * 3600e3 ? 2 : 1);
const clips = $input.all()
  .flatMap(i => i.json.clips || [])
  .filter(c => c.privacy === 'public' && /^https:\/\/clips\.kick\.com\//.test(c.video_url || c.clip_url || ''))
  .filter(c => c.duration >= Number(cfg.min_clip_seconds) && c.duration <= Number(cfg.max_clip_seconds))
  .filter(c => (c.view_count ?? c.views ?? 0) >= Number(cfg.min_views))
  .filter(c => !used.has(c.id))
  .sort((a, b) => score(b) - score(a));

const c = clips.find(x => !recent.has(x.channel?.slug)) || clips[0];
if (!c) return [];
state.used = state.used.concat(c.id).slice(-2000);
state.recent.push({ slug: c.channel?.slug, at: Date.now() });

return [{ json: {
  clipId: c.id,
  clipUrl: c.video_url || c.clip_url,
  clipTitle: c.title,
  views: c.view_count ?? c.views,
  duration: c.duration,
  game: c.category?.name || '',
  streamer: c.channel?.username || c.channel?.slug,
  streamerSlug: c.channel?.slug,
  clipper: c.creator?.username || '',
  createdAt: c.created_at,
} }];

// Trending Turkish gaming/streamer Reels, as wording examples only.
const top = $input.all()
  .map(i => i.json)
  .filter(x => x && !x.error && x.caption)
  .map(x => ({ t: String(x.caption).replace(/\s+/g, ' ').slice(0, 160), v: Number(x.videoPlayCount ?? x.videoViewCount ?? x.likesCount ?? 0) }))
  .sort((a, b) => b.v - a.v)
  .slice(0, 12)
  .map(r => `- [${r.v} izlenme] ${r.t}`);
return [{ json: { ...$('Klibi seç').first().json, styleExamples: top.length ? top.join('\n') : '(örnek alınamadı)' } }];

// Parse Claude's copy and credit the streamer (with a link) in the description and on
// screen. Overlay texts go to the render script base64-encoded.
const src = $('Klibi seç').first().json;
const text = ($input.first().json.content || []).map(c => c.text || '').join('');
const s = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
if (!s.title || !s.hook) throw new Error('Claude yanıtında başlık veya kanca yok: ' + text.slice(0, 200));

const link = `https://kick.com/${src.streamerSlug}`;
const attribution = `🎥 Yayıncı: ${src.streamer} – ${link}\nBu kesit ${src.streamer} yayınından, yayıncının izniyle paylaşılmıştır.`
  + (src.clipper ? `\nKlibi oluşturan: ${src.clipper}` : '');
let title = String(s.title).trim();
if (!/#shorts/i.test(title)) title = (title.length > 90 ? title.slice(0, 90) : title) + ' #Shorts';
const tags = [...new Set([...(s.tags || []), src.streamer, src.game, 'kick', 'yayın kesitleri'].map(t => String(t || '').replace(/[<>,]/g, '').trim()).filter(Boolean))].slice(0, 15);
const runId = new Date().toISOString().replace(/[-:]/g, '').replace(/\..*/, '').replace('T', '-');
const b64 = v => Buffer.from(String(v || ''), 'utf8').toString('base64');

return [{ json: {
  runDir: `${$('Yayıncı ayarları').first().json.output_dir}/yayin-${runId}`,
  clipUrl: src.clipUrl,
  title: title.slice(0, 100),
  description: `${String(s.description).trim()}\n\n${attribution}\n\n#Shorts #${String(src.streamer).replace(/[^\p{L}\p{N}]/gu, '')} #yayınkesitleri`,
  tags: tags.join(','),
  hookB64: b64(String(s.hook).slice(0, 60)),
  creditB64: b64(`Yayıncı: ${src.streamer} (kick.com/${src.streamerSlug})`),
  peakTextB64: b64(String(s.peak_text || ' ').slice(0, 24)),
  endTextB64: b64(String(s.end_text || 'TEKRAR').slice(0, 14)),
} }];

// make-clip.mjs prints one JSON line at the end of stdout.
const lines = String($input.first().json.stdout || '').trim().split('\n');
return [{ json: JSON.parse(lines[lines.length - 1]) }];

const src = $('Klibi seç').first().json;
const clip = $('Kesit sonucunu oku').first().json;
return [{ json: {
  videoId: $input.first().json.id,
  url: `https://youtube.com/shorts/${$input.first().json.id}`,
  title: $('Kesit metinlerini hazırla').first().json.title,
  streamer: src.streamer,
  kickViews: src.views,
  length: `${clip.duration} sn (klip ${src.duration} sn + ağır çekim tekrar)`,
} }];
